// Computes normalized vertical marker positions for the right-edge minimap scrollbar track.

export function computeMinimapMarkers(matches, activeIndex, scrollContainer, maxMarkers = 200) {
  if (!matches || matches.length === 0) return [];

  const isDocScroll =
    !scrollContainer ||
    scrollContainer === document.body ||
    scrollContainer === document.documentElement;

  const containerRect = isDocScroll
    ? { top: 0, height: window.innerHeight || 1 }
    : scrollContainer.getBoundingClientRect();

  const scrollTop = isDocScroll
    ? window.scrollY || document.documentElement.scrollTop || 0
    : scrollContainer.scrollTop;

  const scrollHeight = Math.max(
    1,
    isDocScroll
      ? document.documentElement.scrollHeight || document.body.scrollHeight || 1
      : scrollContainer.scrollHeight
  );

  const raw = [];
  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    if (!m || !m.range || !m.range.startContainer || !m.range.startContainer.isConnected) continue;
    try {
      const rect = m.range.getBoundingClientRect();
      if (rect.width === 0 && rect.height === 0 && rect.top === 0) continue;
      const absTop = isDocScroll
        ? rect.top + scrollTop
        : rect.top - containerRect.top + scrollTop;
      const ratio = Math.min(1, Math.max(0, absTop / scrollHeight));
      raw.push({ index: i, ratio, active: i === activeIndex });
    } catch {
      // Skip detached ranges
    }
  }

  if (raw.length <= maxMarkers) return raw;

  // Bucket into maxMarkers slots while preserving active marker
  const buckets = new Map();
  let activeMarker = null;
  for (const item of raw) {
    if (item.active) {
      activeMarker = item;
      continue;
    }
    const bucket = Math.round(item.ratio * (maxMarkers - 1));
    if (!buckets.has(bucket)) {
      buckets.set(bucket, item);
    }
  }
  const result = Array.from(buckets.values());
  if (activeMarker) result.push(activeMarker);
  return result;
}

