    addIntervalTrigger(site = '', waitAt = 'now', callback, interval_time = 0, runTimes = 1) {
      console.mylog('addIntervalTrigger', site, "------------", this.options.siteName)
      if (site !== 'all' && this.options.siteName !== site) return

