export function createOverlayUI(callbacks, initialLocale = 'zh') {
  let hostEl = null;
  let shadow = null;
  let lang = initialLocale;
  let expanded = false;

  // DOM refs inside shadow root
  let panelEl = null;
  let inputWrapEl = null;
  let inputEl = null;
  let btnCase = null;
  let btnWord = null;
  let btnRegex = null;
  let btnScope = null;
  let btnCount = null;
  let btnPrev = null;
  let btnNext = null;
  let btnClose = null;
  let errorEl = null;
  let listWrapEl = null;
  let minimapEl = null;

  function buildDOM() {
    hostEl = document.createElement('div');
    hostEl.setAttribute('data-chat-find-host', 'true');
    hostEl.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:2147483639;';
    shadow = hostEl.attachShadow({ mode: 'open' });

    const style = document.createElement('style');
    style.textContent = SHADOW_CSS;
    shadow.appendChild(style);

    panelEl = document.createElement('div');
    panelEl.className = 'cf-panel';
    panelEl.setAttribute('role', 'dialog');
    panelEl.setAttribute('aria-label', 'Find in conversation');

    const bar = document.createElement('div');
    bar.className = 'cf-bar';

    inputWrapEl = document.createElement('div');
    inputWrapEl.className = 'cf-input-wrap';
    inputWrapEl.innerHTML = `<svg class="cf-icon-search" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="7" cy="7" r="4.5"/><path d="M10.5 10.5L14 14"/></svg>`;

    inputEl = document.createElement('input');
    inputEl.className = 'cf-input';
    inputEl.type = 'text';
    inputEl.spellcheck = false;
    inputEl.autocomplete = 'off';
    inputWrapEl.appendChild(inputEl);

    btnCase = document.createElement('button');
    btnCase.type = 'button';
    btnCase.className = 'cf-btn cf-btn-mono';
    btnCase.textContent = 'Aa';

    btnWord = document.createElement('button');
    btnWord.type = 'button';
    btnWord.className = 'cf-btn cf-btn-mono';
    btnWord.textContent = '\\b';

    btnRegex = document.createElement('button');
    btnRegex.type = 'button';
    btnRegex.className = 'cf-btn cf-btn-mono';
    btnRegex.textContent = '.*';

    btnScope = document.createElement('button');
    btnScope.type = 'button';
    btnScope.className = 'cf-btn cf-btn-scope';

    const sep1 = document.createElement('span');
    sep1.className = 'cf-sep';

    btnCount = document.createElement('button');
    btnCount.type = 'button';
    btnCount.className = 'cf-btn cf-count-btn';
    btnCount.textContent = '0 / 0';

    btnPrev = document.createElement('button');
    btnPrev.type = 'button';
    btnPrev.className = 'cf-btn';
    btnPrev.innerHTML = `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10l4-4 4 4"/></svg>`;

    btnNext = document.createElement('button');
    btnNext.type = 'button';
    btnNext.className = 'cf-btn';
    btnNext.innerHTML = `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6l4 4 4-4"/></svg>`;

    btnClose = document.createElement('button');
    btnClose.type = 'button';
    btnClose.className = 'cf-btn';
    btnClose.innerHTML = `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>`;

    bar.append(
      inputWrapEl,
      btnCase,
      btnWord,
      btnRegex,
      btnScope,
      sep1,
      btnCount,
      btnPrev,
      btnNext,
      btnClose
    );

    errorEl = document.createElement('div');
    errorEl.className = 'cf-error';

    listWrapEl = document.createElement('div');
    listWrapEl.className = 'cf-list-wrap';

    panelEl.append(bar, errorEl, listWrapEl);

    minimapEl = document.createElement('div');
    minimapEl.className = 'cf-minimap';

    shadow.append(panelEl, minimapEl);

    // Wire events
    inputEl.addEventListener('input', () => {
      callbacks.onQueryChange(inputEl.value);
    });
    inputEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        if (e.shiftKey) callbacks.onPrev();
        else callbacks.onNext();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        callbacks.onClose();
      } else if (e.altKey && !e.ctrlKey && !e.metaKey) {
        const k = e.key.toLowerCase();
        if (k === 'c') { e.preventDefault(); callbacks.onToggleOption('caseSensitive'); }
        else if (k === 'w') { e.preventDefault(); callbacks.onToggleOption('wholeWord'); }
        else if (k === 'r') { e.preventDefault(); callbacks.onToggleOption('regex'); }
      }
    });

    btnCase.addEventListener('click', () => callbacks.onToggleOption('caseSensitive'));
    btnWord.addEventListener('click', () => callbacks.onToggleOption('wholeWord'));
    btnRegex.addEventListener('click', () => callbacks.onToggleOption('regex'));
    btnScope.addEventListener('click', () => callbacks.onToggleScope());
    btnCount.addEventListener('click', () => {
      expanded = !expanded;
      listWrapEl.setAttribute('data-expanded', String(expanded));
      callbacks.onExpandChange(expanded);
    });
    btnPrev.addEventListener('click', () => callbacks.onPrev());
    btnNext.addEventListener('click', () => callbacks.onNext());
    btnClose.addEventListener('click', () => callbacks.onClose());

    applyLocaleStrings('chat');
  }

  function applyLocaleStrings(scopeMode) {
    if (!inputEl) return;
    const t = getMessages(lang);
    inputEl.placeholder = scopeMode === 'page' ? t.placeholderPage : t.placeholder;
    btnCase.title = t.caseSensitive;
    btnWord.title = t.wholeWord;
    btnRegex.title = t.regex;
    btnScope.textContent = scopeMode === 'page' ? t.scopePage : t.scopeChat;
    btnScope.title = scopeMode === 'page' ? t.scopePageTitle : t.scopeChatTitle;
    btnCount.title = t.listToggle;
    btnPrev.title = t.prev;
    btnNext.title = t.next;
    btnClose.title = t.close;
  }

  function mount(parentContainer) {
    if (!hostEl) buildDOM();
    const target = parentContainer || document.body;
    if (target && hostEl.parentNode !== target) {
      target.appendChild(hostEl);
    }
    return hostEl;
  }

  function render(state) {
    if (!panelEl) return;
    const t = getMessages(lang);
    panelEl.setAttribute('data-open', String(state.open));

    if (inputEl.value !== state.query) {
      inputEl.value = state.query;
    }

    btnCase.setAttribute('data-active', String(state.caseSensitive));
    btnWord.setAttribute('data-active', String(state.wholeWord));
    btnRegex.setAttribute('data-active', String(state.regex));
    btnScope.setAttribute('data-active', String(state.scope === 'page'));
    applyLocaleStrings(state.scope);

    // Error state
    const hasError = Boolean(state.error);
    inputWrapEl.setAttribute('data-error', String(hasError));
    errorEl.setAttribute('data-visible', String(hasError));
    errorEl.textContent = hasError ? `${t.regexError}: ${state.error}` : '';

    // Count & navigation buttons
    const total = state.matches.length;
    const hasHits = total > 0;
    const totalLabel = state.truncated ? `${total}+` : `${total}`;
    const caret = expanded ? ' ▴' : ' ▾';
    if (!state.query) {
      btnCount.textContent = `0 / 0`;
    } else if (!hasHits) {
      btnCount.textContent = t.noResults;
    } else {
      btnCount.textContent = `${state.activeIndex + 1} / ${totalLabel}${caret}`;
    }
    btnCount.setAttribute('data-has-hits', String(hasHits));
    btnPrev.disabled = !hasHits;
    btnNext.disabled = !hasHits;

    // Expandable hit list
    listWrapEl.setAttribute('data-expanded', String(state.open && expanded && Boolean(state.query)));
    if (state.open && expanded && state.query) {
      renderHitList(state, t);
    }

    // Minimap markers
    renderMinimap(state);
  }

  function renderHitList(state, t) {
    listWrapEl.textContent = '';
    if (state.matches.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'cf-list-empty';
      empty.textContent = t.emptyList;
      listWrapEl.appendChild(empty);
      return;
    }

    const frag = document.createDocumentFragment();
    const limit = Math.min(state.matches.length, 300);
    for (let i = 0; i < limit; i++) {
      const m = state.matches[i];
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'cf-list-item';
      item.setAttribute('data-active', String(i === state.activeIndex));

      const num = document.createElement('span');
      num.className = 'cf-item-num';
      num.textContent = String(i + 1);

      const snippet = document.createElement('span');
      snippet.className = 'cf-item-snippet';
      if (m.before) snippet.appendChild(document.createTextNode(m.before));
      const hit = document.createElement('span');
      hit.className = 'cf-item-hit';
      hit.textContent = m.text;
      snippet.appendChild(hit);
      if (m.after) snippet.appendChild(document.createTextNode(m.after));

      item.append(num, snippet);
      item.addEventListener('click', () => callbacks.onJumpTo(i));
      frag.appendChild(item);
    }

    if (state.matches.length > limit || state.truncated) {
      const note = document.createElement('div');
      note.className = 'cf-list-note';
      note.textContent = t.truncatedHint.replace('{n}', String(limit));
      frag.appendChild(note);
    }

    listWrapEl.appendChild(frag);

    // Keep active item visible inside dropdown
    const activeItem = listWrapEl.querySelector('.cf-list-item[data-active="true"]');
    if (activeItem && typeof activeItem.scrollIntoView === 'function') {
      activeItem.scrollIntoView({ block: 'nearest' });
    }
  }

  function renderMinimap(state) {
    if (!minimapEl) return;
    const markers = state.markers || [];
    const visible = state.open && markers.length > 0;
    minimapEl.setAttribute('data-visible', String(visible));
    minimapEl.textContent = '';
    if (!visible) return;

    const frag = document.createDocumentFragment();
    for (const mk of markers) {
      const dot = document.createElement('div');
      dot.className = 'cf-marker';
      dot.style.top = `${(mk.ratio * 100).toFixed(2)}%`;
      if (mk.active) dot.setAttribute('data-active', 'true');
      dot.addEventListener('click', () => callbacks.onJumpTo(mk.index));
      frag.appendChild(dot);
    }
    minimapEl.appendChild(frag);
  }

  function focusInput(selectAll = true) {
    if (!inputEl) return;
    requestAnimationFrame(() => {
      try {
        inputEl.focus({ preventScroll: true });
        if (selectAll) inputEl.select();
      } catch {
        // Ignore focus errors
      }
    });
  }

  function setLocale(nextLang) {
    lang = nextLang || 'en';
  }

  function setExpanded(value) {
    expanded = Boolean(value);
  }

  function dispose() {
    if (hostEl && hostEl.parentNode) {
      hostEl.parentNode.removeChild(hostEl);
    }
    hostEl = null;
    shadow = null;
    panelEl = null;
  }

  return {
    mount,
    render,
    focusInput,
    setLocale,
    setExpanded,
    dispose,
    getHostElement: () => hostEl,
  };
}

