// Smart scope resolver: identifies conversation container in DSH, Codex, Antigravity, and generic web apps.

const CHAT_SELECTORS = [
  '[data-conversation-scroll]',
  '[data-conversation-content]',
  '[data-testid="conversation-turns"]',
  '[data-testid="conversation-panel"]',
  'main [role="log"]',
  'main',
  '[role="main"]',
  '.conversation-container',
  '.chat-messages',
];

function isScrollable(el) {
  if (!el || el === document.body || el === document.documentElement) return false;
  try {
    const style = getComputedStyle(el);
    const overflowY = style.overflowY;
    return (
      (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'overlay') &&
      el.scrollHeight > el.clientHeight + 4
    );
  } catch {
    return false;
  }
}

function findScrollContainer(el) {
  if (!el) return null;
  if (isScrollable(el)) return el;
  let cur = el.parentElement;
  while (cur && cur !== document.body && cur !== document.documentElement) {
    if (isScrollable(cur)) return cur;
    cur = cur.parentElement;
  }
  return el.scrollHeight > el.clientHeight ? el : null;
}

function detectSessionKey() {
  const conv = document.querySelector('[data-conversation-session]');
  if (conv) {
    return conv.getAttribute('data-conversation-session') || '';
  }
  return `${location.pathname}${location.search}${location.hash}`;
}

export function resolveScope(scopeMode = 'chat', adapterHint = 'generic') {
  const baseExclude = ['[data-chat-find-host]'];
  const sessionKey = detectSessionKey();

  if (scopeMode === 'page') {
    return {
      roots: document.body ? [document.body] : [],
      scrollContainer: findScrollContainer(document.querySelector('[data-conversation-scroll]')) || document.scrollingElement || document.documentElement,
      excludeSelectors: baseExclude,
      sessionKey,
      resolvedAs: 'page',
    };
  }

  // Chat scope: prioritize DSH conversation scroll container
  if (adapterHint === 'dsh') {
    const dshScroll = document.querySelector('[data-conversation-scroll]');
    if (dshScroll) {
      return {
        roots: [dshScroll],
        scrollContainer: dshScroll,
        excludeSelectors: [...baseExclude, '[data-composer-seat]', '[data-conversation-region="composer"]'],
        sessionKey,
        resolvedAs: 'chat',
      };
    }
  }

  for (const selector of CHAT_SELECTORS) {
    const candidate = document.querySelector(selector);
    if (candidate && candidate.innerText && candidate.innerText.trim().length > 0) {
      return {
        roots: [candidate],
        scrollContainer: findScrollContainer(candidate) || document.scrollingElement || document.documentElement,
        excludeSelectors: [
          ...baseExclude,
          '[data-composer-seat]',
          '[data-conversation-region="composer"]',
          'nav',
          'aside',
          'form',
          '[contenteditable="true"]',
        ],
        sessionKey,
        resolvedAs: 'chat',
      };
    }
  }

  // Fallback to full page when no conversation container is mounted (e.g., Settings / Plugins view)
  return {
    roots: document.body ? [document.body] : [],
    scrollContainer: document.scrollingElement || document.documentElement,
    excludeSelectors: baseExclude,
    sessionKey,
    resolvedAs: 'page',
  };
}

