// Core search engine: pure pattern compiler + DOM TreeWalker block-aware matcher.

const BLOCK_TAGS = new Set([
  'ADDRESS', 'ARTICLE', 'ASIDE', 'BLOCKQUOTE', 'CAPTION', 'DD', 'DETAILS',
  'DIALOG', 'DIV', 'DL', 'DT', 'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER',
  'FORM', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'HEADER', 'HGROUP', 'HR',
  'LI', 'MAIN', 'NAV', 'OL', 'P', 'PRE', 'SECTION', 'SUMMARY', 'TABLE',
  'TBODY', 'TD', 'TFOOT', 'TH', 'THEAD', 'TR', 'UL',
]);

const SKIP_TAGS = new Set([
  'SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'TEXTAREA', 'INPUT', 'SELECT',
  'OPTION', 'SVG', 'CANVAS', 'AUDIO', 'VIDEO', 'IFRAME', 'OBJECT', 'EMBED',
]);

export function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function compilePattern(query, options = {}) {
  if (!query || typeof query !== 'string') {
    return { regex: null, error: null };
  }
  const caseSensitive = Boolean(options.caseSensitive);
  const wholeWord = Boolean(options.wholeWord);
  const isRegex = Boolean(options.regex);
  const flags = caseSensitive ? 'g' : 'gi';

  let source = isRegex ? query : escapeRegExp(query);
  if (wholeWord && !isRegex) {
    const startWord = /^[A-Za-z0-9_]/.test(query);
    const endWord = /[A-Za-z0-9_]$/.test(query);
    source = `${startWord ? '\\b' : ''}${source}${endWord ? '\\b' : ''}`;
  } else if (wholeWord && isRegex) {
    source = `\\b(?:${source})\\b`;
  }

  try {
    const regex = new RegExp(source, flags);
    return { regex, error: null };
  } catch (err) {
    return { regex: null, error: err instanceof Error ? err.message : String(err) };
  }
}

export function findMatchesInText(text, regex, maxRemaining = 2000) {
  if (!text || !regex || maxRemaining <= 0) return { hits: [], truncated: false };
  regex.lastIndex = 0;
  const hits = [];
  let truncated = false;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const len = match[0].length;
    if (len === 0) {
      regex.lastIndex += 1;
      if (regex.lastIndex > text.length) break;
      continue;
    }
    if (hits.length >= maxRemaining) {
      truncated = true;
      break;
    }
    hits.push({
      start: match.index,
      end: match.index + len,
      text: match[0],
    });
  }
  return { hits, truncated };
}

export function buildContextSnippet(fullText, start, end, radius = 28) {
  const clean = (s) => s.replace(/\s+/g, ' ');
  const beforeRaw = fullText.slice(Math.max(0, start - radius), start);
  const afterRaw = fullText.slice(end, Math.min(fullText.length, end + radius));
  const before = (start > radius ? '…' : '') + clean(beforeRaw);
  const after = clean(afterRaw) + (end + radius < fullText.length ? '…' : '');
  return { before, after };
}

function getBlockAncestor(node, stopRoot) {
  let cur = node.parentElement;
  while (cur && cur !== stopRoot) {
    if (BLOCK_TAGS.has(cur.tagName)) return cur;
    cur = cur.parentElement;
  }
  return stopRoot;
}

function isElementSkipped(el, excludeSelector) {
  if (!el) return true;
  if (SKIP_TAGS.has(el.tagName)) return true;
  if (el.hidden || el.getAttribute('aria-hidden') === 'true') return true;
  if (excludeSelector && el.closest(excludeSelector)) return true;
  if (el.offsetParent === null) {
    const style = typeof getComputedStyle === 'function' ? getComputedStyle(el) : null;
    if (style && (style.display === 'none' || style.visibility === 'hidden')) return true;
    if (style && style.position !== 'fixed' && style.position !== 'sticky') {
      if (typeof el.getClientRects === 'function' && el.getClientRects().length === 0) return true;
    }
  }
  return false;
}

function resolveOffset(segments, targetOffset) {
  // Binary search over segments [{ node, start, end }]
  let lo = 0;
  let hi = segments.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const seg = segments[mid];
    if (targetOffset < seg.start) {
      hi = mid - 1;
    } else if (targetOffset >= seg.end) {
      lo = mid + 1;
    } else {
      return { node: seg.node, offset: targetOffset - seg.start };
    }
  }
  const last = segments[segments.length - 1];
  return { node: last.node, offset: last.end - last.start };
}

function resolveEndOffset(segments, targetEnd) {
  // End offset is exclusive, so targetEnd === seg.end maps to end of seg.node
  let lo = 0;
  let hi = segments.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const seg = segments[mid];
    if (targetEnd <= seg.start) {
      hi = mid - 1;
    } else if (targetEnd > seg.end) {
      lo = mid + 1;
    } else {
      return { node: seg.node, offset: targetEnd - seg.start };
    }
  }
  const last = segments[segments.length - 1];
  return { node: last.node, offset: last.end - last.start };
}

export function searchDOM(roots, query, options = {}) {
  const maxMatches = options.maxMatches ?? 2000;
  const excludeSelectors = options.excludeSelectors ?? ['[data-chat-find-host]'];
  const excludeSelector = excludeSelectors.filter(Boolean).join(', ');
  const { regex, error } = compilePattern(query, options);

  if (error) {
    return { matches: [], truncated: false, error };
  }
  if (!regex || !roots || roots.length === 0) {
    return { matches: [], truncated: false, error: null };
  }

  const blockMap = new Map();
  const blockOrder = [];

  for (const root of roots) {
    if (!root || !root.isConnected) continue;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !node.nodeValue.trim()) {
          // Keep single spaces between inline elements inside a block if non-empty
          if (!node.nodeValue) return NodeFilter.FILTER_REJECT;
        }
        const parent = node.parentElement;
        if (!parent || isElementSkipped(parent, excludeSelector)) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      },
    });

    let textNode;
    while ((textNode = walker.nextNode())) {
      const blockEl = getBlockAncestor(textNode, root);
      let entry = blockMap.get(blockEl);
      if (!entry) {
        entry = { blockEl, text: '', segments: [] };
        blockMap.set(blockEl, entry);
        blockOrder.push(entry);
      }
      const val = textNode.nodeValue || '';
      const start = entry.text.length;
      const end = start + val.length;
      entry.text += val;
      entry.segments.push({ node: textNode, start, end });
    }
  }

  const matches = [];
  let truncated = false;

  for (const entry of blockOrder) {
    if (matches.length >= maxMatches) {
      truncated = true;
      break;
    }
    const remaining = maxMatches - matches.length;
    const { hits, truncated: blockTruncated } = findMatchesInText(entry.text, regex, remaining);
    if (blockTruncated) truncated = true;

    for (const hit of hits) {
      const startPos = resolveOffset(entry.segments, hit.start);
      const endPos = resolveEndOffset(entry.segments, hit.end);
      try {
        const range = document.createRange();
        range.setStart(startPos.node, startPos.offset);
        range.setEnd(endPos.node, endPos.offset);
        const snippet = buildContextSnippet(entry.text, hit.start, hit.end, 28);
        matches.push({
          index: matches.length,
          range,
          text: hit.text,
          before: snippet.before,
          after: snippet.after,
          blockEl: entry.blockEl,
        });
      } catch {
        // Ignore stale or invalid DOM range
      }
    }
  }

  return { matches, truncated, error: null };
}

