(() => {
  const GUARD = "__yt_unified_optimizer__";
  if (window[GUARD]) return;
  window[GUARD] = 1;
  const K = {
    RAF_BASE: 1e9,
    RAF_BATCH: 8,
    PREFETCH_TO: 3e4,
    SCROLL_DB: 60,
    WHEEL_DB: 60,
    RESIZE_DB: 120,
    INSTANT_NAV_TH: 200,
    QUALITY_INIT: 120,
    QUALITY_RETRY: 120,
