// Based on "Dark mode" by Michael Wang (https://greasyfork.org/scripts/472251), MIT licensed.

(() => {
  'use strict';

  const root = document.documentElement;
  if (!(root instanceof HTMLHtmlElement)) return; // raw SVG/XML files

  // ---- Tuning ---------------------------------------------------------------
  const CONTRAST = 0.8; // below 1 softens the inverted page
  // true: page colours keep their hue (blue links stay blue), but strongly saturated reds,
  //       purples and yellows inside images shift a little.
  // false: images come back with exact colours, but page accents flip to their opposite (blue links turn orange).
  const KEEP_HUES = true;
  const DARK_BELOW = 0.4; // relative luminance under this counts as a dark background
  const OPAQUE = 0.9; // backgrounds less opaque than this are see-through (modal backdrops)
  const SAMPLES = [[0.5, 0.5], [0.25, 0.3], [0.75, 0.3], [0.25, 0.75], [0.75, 0.75]];
  const THEME_ATTRS = ['class', 'style', 'data-theme', 'data-color-mode', 'data-color-scheme',
    'data-bs-theme', 'data-mode', 'theme', 'dark'];

  const ON = 'data-smart-dark';
  const BGIMG = 'data-smart-dark-img'; // set on elements whose CSS background is a picture
  const KEY = 'mode:' + location.hostname;
  const MODES = { auto: 'Auto (detect)', on: 'Always dark', off: 'Never' };
  const hasGM = typeof GM_getValue === 'function';
  const getMode = () => (hasGM ? GM_getValue(KEY, 'auto') : 'auto');

  // ---- Styles ---------------------------------------------------------------
  // Media gets the exact inverse of the page filter (contrast first), so photos keep
  // their real colours and contrast. Anything inside an element that is already flipped back
  // (<img> in <picture>, an <img> on a background-image banner) is skipped, or it would flip twice.
  const HUE = KEEP_HUES ? ' hue-rotate(180deg)' : '';
  const mainCss = `
    @media screen {
      html[${ON}] { filter: invert(1)${HUE} contrast(${CONTRAST}) !important; }
      html[${ON}] :is(img, picture, video, canvas, iframe, frame, embed, object, [${BGIMG}]):not(:is(picture, video, object, [${BGIMG}]) *) {
        filter: contrast(${1 / CONTRAST}) invert(1)${HUE} !important;
      }
    }`;
  const mainStyle = document.createElement('style');
  mainStyle.textContent = mainCss;
  // The filter doesn't reach the page canvas, so a page with no background of its own
  // would stay white under light text. This paints the canvas colour onto <html> itself.
  const fillStyle = document.createElement('style');

  const ensureStyles = () => {
    const parent = document.head || root;
    if (!mainStyle.isConnected) parent.appendChild(mainStyle);
    if (!fillStyle.isConnected) parent.appendChild(fillStyle);
  };

  // ---- Colour maths ---------------------------------------------------------
  const ctx = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
  const cache = new Map();
  function rgba(color) {
    if (cache.has(color)) return cache.get(color);
    let c;
    const m = /^rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?\)$/.exec(color);
    if (m) {
      c = { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] };
    } else {
      // oklch(), lab(), color(display-p3 ...) and friends: let the browser convert.
      ctx.clearRect(0, 0, 1, 1);
      ctx.fillStyle = 'rgba(0,0,0,0)';
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 1, 1);
      const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
      c = { r, g, b, a: a / 255 };
    }
    cache.set(color, c);
    return c;
  }
  const lin = (v) => ((v /= 255) <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const luminance = ({ r, g, b }) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  const bg = (el) => rgba(getComputedStyle(el).backgroundColor);

  // What the browser paints behind everything when neither <html> nor <body> sets a background.
  function defaultCanvas() {
    let scheme = getComputedStyle(root).colorScheme || 'normal';
    if (scheme === 'normal') scheme = document.querySelector('meta[name="color-scheme"]')?.content || 'light';
    const s = scheme.split(/\s+/);
    const dark = s.includes('dark') && (!s.includes('light') || matchMedia('(prefers-color-scheme: dark)').matches);
    return dark ? { r: 18, g: 18, b: 18, a: 1 } : { r: 255, g: 255, b: 255, a: 1 };
  }

  const SKIP = new Set(['IMG', 'PICTURE', 'VIDEO', 'CANVAS', 'IFRAME', 'FRAME', 'EMBED', 'OBJECT']);
  function backgroundAt(x, y) {
    for (const el of document.elementsFromPoint(x, y)) {
      if (SKIP.has(el.tagName) || el instanceof SVGElement) continue;
      const c = bg(el);
      if (c.a >= OPAQUE) return c;
    }
    return null;
  }

  // Looks at what is actually painted at five points of the viewport and takes the majority.
  function measure() {
    fillStyle.disabled = true; // read the page's own colours, not our fill
    const rootBg = bg(root);
    const bodyBg = document.body ? bg(document.body) : { a: 0 };
    fillStyle.disabled = false;
    const canvas = rootBg.a >= OPAQUE ? rootBg : bodyBg.a >= OPAQUE ? bodyBg : defaultCanvas();

    const w = innerWidth, h = innerHeight;
    let darkVotes = 0;
    for (const [fx, fy] of SAMPLES) {
      const c = (w && h && backgroundAt(fx * w, fy * h)) || canvas;
      if (luminance(c) < DARK_BELOW) darkVotes++;
    }
    return {
      dark: darkVotes * 2 > SAMPLES.length,
      fill: rootBg.a >= OPAQUE ? '' : `rgb(${canvas.r},${canvas.g},${canvas.b})`,
    };
  }

  // ---- Apply ----------------------------------------------------------------
  const isFullscreen = () => !!(document.fullscreenElement || document.webkitFullscreenElement);
  let want = false;

  function apply() {
    if (!document.body) return;
    ensureStyles();
    const mode = getMode();
    const { dark, fill } = measure();
    // Fullscreen elements render outside <html>'s filter, so the media un-invert
    // would leave a fullscreen video inverted. Switch off while fullscreen.
    want = !isFullscreen() && (mode === 'on' || (mode === 'auto' && !dark));
    const css = want && fill ? `@media screen { html[${ON}] { background-color: ${fill} !important; } }` : '';
    if (fillStyle.textContent !== css) fillStyle.textContent = css;
    if (root.hasAttribute(ON) !== want) root.toggleAttribute(ON, want);
    if (!want) scannedOnce = false; // content added while off gets scanned when it turns back on
    else if (!scannedOnce) { scannedOnce = true; markBackgroundImages(document.body); }
  }

  // ---- CSS background images ------------------------------------------------
  // <img> is easy to match with CSS; a photo set as background-image isn't, so find those.
  // Elements holding a lot of text are left inverted: there the image is a texture behind
  // content, and un-inverting would bring back a light section.
  let scannedOnce = false;
  function checkBackground(el) {
    if (el.hasAttribute(BGIMG) || el === document.body || SKIP.has(el.tagName) || el instanceof SVGElement) return;
    if (getComputedStyle(el).backgroundImage.includes('url(') && el.textContent.length < 200) el.setAttribute(BGIMG, '');
  }
  function markBackgroundImages(scope) {
    if (scope.nodeType !== 1) return;
    checkBackground(scope);
    for (const el of scope.getElementsByTagName('*')) checkBackground(el);
  }
  // New content (infinite scroll, lazy loaders that set style="background-image: ..." later).
  const pendingImg = new Set();
  let imgTimer = 0;
  const imgObserver = new MutationObserver((records) => {
    for (const r of records) {
      if (r.type === 'attributes') pendingImg.add(r.target);
      else r.addedNodes.forEach((n) => n.nodeType === 1 && pendingImg.add(n));
    }
    if (imgTimer) return;
    imgTimer = setTimeout(() => {
      imgTimer = 0;
      if (want) {
        for (const n of pendingImg) {
          if (!n.isConnected) continue;
          if (n === document.body) checkBackground(n);
          else markBackgroundImages(n);
        }
      }
      pendingImg.clear();
    }, 200);
  });

  let queued = false;
  const schedule = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; apply(); });
  };

  // First run just before first paint: render-blocking CSS is loaded by then, so
  // dark pages never flash white and light pages never flash light.
  requestAnimationFrame(function first() { document.body ? apply() : requestAnimationFrame(first); });
  document.addEventListener('DOMContentLoaded', schedule);
  addEventListener('load', () => { schedule(); setTimeout(schedule, 1000); setTimeout(schedule, 3000); });

  // The site switching its own theme, or a framework wiping our attribute.
  const themeObserver = new MutationObserver((records) => {
    if (records.some((r) => r.attributeName !== ON)) schedule();
    else if (root.hasAttribute(ON) !== want) root.toggleAttribute(ON, want);
  });
  themeObserver.observe(root, { attributes: true, attributeFilter: [...THEME_ATTRS, ON] });

  // Body: theme classes, plus the first seconds of content mounting (SPAs that paint an empty page first).
  let throttle = 0;
  const contentObserver = new MutationObserver(() => {
    const now = performance.now();
    if (now - throttle > 250) { throttle = now; schedule(); }
  });
  (function watchBody() {
    if (!document.body) return requestAnimationFrame(watchBody);
    themeObserver.observe(document.body, { attributes: true, attributeFilter: ['class', 'data-theme', 'data-color-mode', 'data-bs-theme'] });
    contentObserver.observe(document.body, { childList: true, subtree: true });
    addEventListener('load', () => setTimeout(() => contentObserver.disconnect(), 10000));
    imgObserver.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['style', 'class'] });
    // Stylesheets that arrive late can add background images to elements already scanned.
    addEventListener('load', () => { if (want) markBackgroundImages(document.body); else scannedOnce = false; });
  })();

  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', schedule);
  document.addEventListener('fullscreenchange', apply);
  document.addEventListener('webkitfullscreenchange', apply);
  // Client-side navigation can swap a light page for a dark one.
  window.navigation?.addEventListener('navigatesuccess', () => setTimeout(schedule, 300));
  addEventListener('popstate', () => setTimeout(schedule, 300));

  // ---- Per-site menu (top frame only, or Tampermonkey lists it once per iframe) ----
  if (!hasGM) return;
  const isTop = window.top === window.self;
  // Keeps other tabs and same-site iframes in step when the mode changes.
  if (typeof GM_addValueChangeListener === 'function') {
    GM_addValueChangeListener(KEY, (_k, _old, _new, remote) => { if (isTop) buildMenu(); if (remote) schedule(); });
  }
  if (!isTop) return;
  let menuIds = [];
  function buildMenu() {
    menuIds.forEach((id) => GM_unregisterMenuCommand?.(id));
    const current = getMode();
    menuIds = Object.entries(MODES).map(([mode, label]) =>
      GM_registerMenuCommand(`${mode === current ? '[x] ' : '[ ] '}${label} on ${location.hostname}`, () => {
        GM_setValue(KEY, mode);
        buildMenu();
        apply();
      }));
  }
  buildMenu();
})();

