const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, '..');
const coreDir = path.join(rootDir, 'core');

const CORE_FILES = [
  'search-engine.js',
  'highlighter.js',
  'scope-resolver.js',
  'live-observer.js',
  'minimap-markers.js',
  'overlay-ui.js',
