function stripModuleSyntax(source, filename) {
  return (
    `  // --- core/${filename} ---\n` +
    source
      .replace(/^import\s+[\s\S]*?from\s+['"][^'"]+['"];?\s*$/gm, '')
      .replace(/^export\s+(?=(?:async\s+)?function\s+|const\s+|let\s+|class\s+)/gm, '')
      .trim()
  );
}

function buildCoreBlock() {
  const parts = CORE_FILES.map((file) => {
    const content = fs.readFileSync(path.join(coreDir, file), 'utf8');
    return stripModuleSyntax(content, file);
  });
  return `function createChatFindRuntime() {\n${parts.join('\n\n')}\n  return { createChatFindController };\n}`;
}

function writeFileEnsureDir(filePath, content) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content, 'utf8');
}

function buildDshClient(coreBlock) {
