  factory(require) {
    const React = require('react');
    const h = React.createElement;

${coreBlock}

    const { createChatFindController } = createChatFindRuntime();

    return {
      inject: ['slots'],
      apply(ctx) {
        let activeController = null;
        let currentLocale = 'zh';

        const resolveLocale = () => {
          try {
            const loc = ctx.get && ctx.get('locale');
            if (loc && typeof loc.getSnapshot === 'function') {
              const snap = loc.getSnapshot();
              if (snap && snap.active) return snap.active;
            }
          } catch {}
          return typeof navigator !== 'undefined' ? navigator.language : 'en';
        };

        currentLocale = resolveLocale();

        ctx.effect(() => {
          const loc = ctx.get && ctx.get('locale');
          if (!loc || typeof loc.subscribe !== 'function') return;
          return loc.subscribe(() => {
            currentLocale = resolveLocale();
            if (activeController) activeController.setLocale(currentLocale);
          });
        }, 'dsh-chat-find: locale sync');

        ctx.effect(() => {
          const shortcuts = ctx.get && ctx.get('shortcuts');
          if (!shortcuts || typeof shortcuts.register !== 'function') return;
          try {
            return shortcuts.register({
              id: 'dsh-chat-find.open',
              label: () => (currentLocale.startsWith('zh') ? '会话内查找' : 'Find in conversation'),
              aliases: ['find', 'search', 'chat find', '查找', '搜索'],
              defaults: {
                'desktop:macos': { code: 'KeyF', modifiers: ['primary'] },
                'desktop:windows': { code: 'KeyF', modifiers: ['primary'] },
                'desktop:linux': { code: 'KeyF', modifiers: ['primary'] },
                'web:macos': { code: 'KeyF', modifiers: ['primary', 'shift'] },
                'web:windows': { code: 'KeyF', modifiers: ['primary', 'shift'] },
              },
              regions: ['page', 'editable'],
              modals: [],
              resolve({ modal, region }) {
                if (region === 'terminal' || modal !== null) return { status: 'pass' };
                return {
                  status: 'handled',
                  run() {
                    if (activeController) activeController.open();
                  },
                };
              },
            });
          } catch {
            return undefined;
          }
        }, 'dsh-chat-find: shortcut registration');

        function ChatFindHeaderButton() {
          const isZh = currentLocale.startsWith('zh');
          const label = isZh ? '会话内查找 (Ctrl+F)' : 'Find in conversation (Ctrl+F)';
          return h(
            'button',
            {
              type: 'button',
              title: label,
              'aria-label': label,
              'data-chat-find-trigger': 'true',
              onClick() {
                if (activeController) activeController.toggle();
              },
              style: {
                appearance: 'none',
