              },
              h('circle', { cx: 7, cy: 7, r: 4.5 }),
              h('path', { d: 'M10.5 10.5L14 14' })
            )
          );
        }

        function ChatFindOverlay() {
          const containerRef = React.useRef(null);

          React.useEffect(() => {
            const el = containerRef.current;
            if (!el) return;
            const ctrl = createChatFindController({
              adapterHint: 'dsh',
              locale: resolveLocale(),
              mountContainer: el,
            });
            activeController = ctrl;
            ctrl.mount(el);
            return () => {
              if (activeController === ctrl) activeController = null;
              ctrl.dispose();
            };
          }, []);

          return h('div', {
            ref: containerRef,
            'data-chat-find-slot': 'true',
            style: { pointerEvents: 'none' },
          });
