          )
        );

        ctx.slots.inject('shell.overlay', () =>
          ctx.slots.register(
            {
              name: 'shell.overlay',
              id: 'dsh-chat-find',
              order: 50,
            },
            ChatFindOverlay
          )
        );
      },
    };
  },
});
`;
}

