// Loads a dark mode script into a test page from <head>, before <body> exists,
// the same moment Tampermonkey runs a script with @run-at document-start.
//   (no query)  the current smart-dark-mode.user.js
//   ?v=exact    the same script with KEEP_HUES = false (served by run.mjs)
//   ?v=orig     the original "Dark mode" script this project started from
//   ?v=none     no script, the page as its author made it
const v = new URLSearchParams(location.search).get('v');
const SOURCES = { orig: 'original.user.js', exact: '../exact.user.js', none: '' };
const src = v in SOURCES ? SOURCES[v] : '../smart-dark-mode.user.js';
if (src) document.write('<script src="gm-stub.js"><\/script><script src="' + src + '"><\/script>');

