// Runs every test page in headless Chrome and checks what the script did.
//   npm test                  the current script
//   npm run test:original     the original script, to see the failures this project fixes
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright-core';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const ORIGINAL = process.argv.includes('--original');
const Q = ORIGINAL ? '?v=orig' : '';

// ---- Static server for the repo -------------------------------------------
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  try {
    let body;
    if (pathname === '/exact.user.js') {
      body = (await readFile(join(ROOT, 'smart-dark-mode.user.js'), 'utf8'))
        .replace('const KEEP_HUES = true;', 'const KEEP_HUES = false;');
      if (!body.includes('const KEEP_HUES = false;')) throw new Error('KEEP_HUES line not found');
    } else {
      const file = normalize(join(ROOT, decodeURIComponent(pathname)));
      if (!file.startsWith(ROOT.endsWith(sep) ? ROOT : ROOT + sep)) throw new Error('outside repo');
      body = await readFile(file);
    }
    res.writeHead(200, { 'content-type': TYPES[extname(pathname)] || 'application/octet-stream', 'cache-control': 'no-store' });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end();
  }
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const BASE = `http://127.0.0.1:${server.address().port}/tests/`;

// ---- Browser ----------------------------------------------------------------
// Uses the Chrome you already have, so there is no browser download. Set CHROME_PATH to use another Chromium.
const browser = await chromium.launch(process.env.CHROME_PATH
  ? { executablePath: process.env.CHROME_PATH }
  : { channel: 'chrome' });
const context = await browser.newContext({ viewport: { width: 800, height: 900 }, deviceScaleFactor: 1, colorScheme: 'light' });
const page = await context.newPage();
const decoder = await context.newPage();

let failures = 0;
const report = (ok, name, detail = '') => {
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
};

const isInverted = () => page.evaluate(() => getComputedStyle(document.documentElement).filter !== 'none');

// Reads the average colour of a 5x5 patch at each point of a PNG screenshot.
async function pixels(png, points) {
  return decoder.evaluate(async ({ b64, points }) => {
    const img = new Image();
    img.src = 'data:image/png;base64,' + b64;
    await img.decode();
    const c = Object.assign(document.createElement('canvas'), { width: img.width, height: img.height });
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    return Object.fromEntries(Object.entries(points).map(([k, [x, y]]) => {
      const d = ctx.getImageData(x - 2, y - 2, 5, 5).data;
      const sum = [0, 0, 0];
      for (let i = 0; i < d.length; i += 4) { sum[0] += d[i]; sum[1] += d[i + 1]; sum[2] += d[i + 2]; }
      return [k, sum.map((s) => Math.round(s / 25))];
    }));
  }, { b64: png.toString('base64'), points });
}
const luminance = ([r, g, b]) => (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
const delta = (a, b) => Math.max(...a.map((v, i) => Math.abs(v - b[i])));

// ---- 1. Dark or light: each page says what it expects in <meta name="expect"> ----
const PAGES = ['light-plain', 'dark-body', 'dark-wrapper', 'dark-oklch', 'dark-colorscheme',
  'light-modal', 'light-hero', 'late-dark', 'spa-dark'];
for (const name of PAGES) {
  await page.goto(BASE + name + '.html' + Q);
  await page.waitForTimeout(1500); // late-dark and spa-dark change 400 to 500 ms after load
