    const succeeded=record.phase==='available'||record.phase==='current';
    let comparison=null;
    // The remote version and throttle are shared. Older open pages may run a different build.
    if(succeeded)try{comparison=UpdateCheck.compareVersions(record.version,SCRIPT_VERSION);}catch{}
