    if(busy)updateExpiryTimer=setTimeout(paintUpdates,Math.max(1,record.attemptAt+UPDATE_LEASE-Date.now()));
    const status=$('[data-update-status]');
    if(!status)return;
    $('[name=update-mode]').value=prefs.mode;
    $('[name=update-source]').value=prefs.source;
    const check=$('[data-action=check-update]'),install=$('[data-update-install]');
    check.disabled=busy;
    $('[data-action=choose-update-source]').hidden=record.phase!=='error';
    install.hidden=!available;
    if(available)install.href=UpdateCheck.sources[prefs.source].installUrl;
    else install.removeAttribute('href');
    let message='尚未检查此来源。';
    if(busy)message='正在检查 '+UpdateCheck.sources[prefs.source].label+'…';
    else if(available)message='发现新版本 '+record.version+'。';
    else if(comparison!==null)message='当前无需更新，来源提供的版本为 '+record.version+'。';
