async function copyText(text) {
    if(typeof text!=='string'||!text.trim()){toast('没有可复制的内容');return false;}
    if(copyBusy){toast('正在复制，请稍候再试');return false;}
    copyBusy=true;
    toast('正在复制…');
    const verify=async()=>{
        // Read only when already authorised; never trigger a clipboard-read prompt.
        try{if(!navigator.clipboard?.readText||!navigator.permissions?.query)return true;
            const permission=await navigator.permissions.query({name:'clipboard-read'});if(permission.state!=='granted')return true;
            return (await navigator.clipboard.readText()).replace(/\r\n/g,'\n')===text.replace(/\r\n/g,'\n');
        }catch{return true;}
    };
    try{
        let copied=false;
        try{
            clipboardBridgeActive=true;
            try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('剪贴板响应超时')),3000);try{GM_setClipboard(text,{type:'text',mimetype:'text/plain'},error=>{clearTimeout(timer);error?reject(Error('复制接口返回错误')):resolve();});}catch(error){clearTimeout(timer);reject(error);}});}
            finally{clipboardBridgeActive=false;}
            copied=await verify();
        }catch{}
        if(!copied){try{await navigator.clipboard.writeText(text);copied=await verify();}catch{}}
        if(copied){toast('已复制到剪贴板');return true;}
        toast('自动复制未完成，请手动复制');
        dialog('请手动复制',`<p>未能完成自动复制。正文已选中，按 Ctrl / ⌘ + C 复制后再粘贴。</p><textarea class="input" readonly aria-label="待复制的完整内容">${esc(text)}</textarea>`,()=>{}, {label:'完成'});
        $('.dialog textarea').focus();$('.dialog textarea').select();return false;
    }finally{clipboardBridgeActive=false;copyBusy=false;}
}
