        if(el.name==='launcherSize'){updateLauncherPreview(el.value);return;}
        if(el.classList.contains('search-input')){query=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(renderList,100);return;}
        if(view==='editor'&&form?.usingTool){
            if(el.name==='source')form.source=el.value;
            if(el.name==='content'){
                const previous=toolVariableNames(form.content);
                form.content=el.value;
                const next=toolVariableNames(form.content);
                if(JSON.stringify(previous)!==JSON.stringify(next)){
                    for(const key of previous)if(!next.includes(key))delete form.values[key];
                    renderToolUseFields();
                }
                updateVariableHighlight();
            }
            if(el.name.startsWith('tool-var-')){
                const key=toolVariableNames(form.content)[Number(el.name.slice(9))];
                if(el.value)form.values[key]=el.value;else delete form.values[key];
