function handleHelperKeydown(e){
    if(e.isComposing||e.keyCode===229)return;
    if(!$('.overlay').hidden){
        if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeDialog();return;}
        if(e.key==='Tab'){
            const controls=[...$('.dialog').querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled),index=controls.indexOf(shadow.activeElement);
            if(e.shiftKey&&index<=0){controls.at(-1)?.focus();e.preventDefault();}else if(!e.shiftKey&&index===controls.length-1){controls[0]?.focus();e.preventDefault();}
        }return;
    }
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopPropagation();navigate('library',{focusSearch:true});}
    if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&form){e.preventDefault();e.stopPropagation();if(form.mode==='use')copyText(currentOutput());else try{savePrompt();}catch(error){toast(error.message);}}
    if(e.key==='Escape'&&navigation.length){e.preventDefault();e.stopPropagation();back();}
}
