        const { surface, kind } = disclosure;
        const message = surface.closest('[data-dil-message-id], [data-response-body], [data-message-id]');
        const scope = message && wrapper.contains(message) ? message : null;
        const messageId = scope && (scope.getAttribute('data-dil-message-id') ||
            scope.getAttribute('data-response-body') || scope.getAttribute('data-message-id'));
        if (!messageId) return null;
        const selector = kind === 'writing' ? WRITING_SURFACE : CODE_SURFACE;
        const index = Array.from(scope.querySelectorAll(selector)).indexOf(surface);
        if (index < 0) return null;
        const widgetId = surface.closest('[data-client-defined-widget="writing_block"]')?.getAttribute('data-id') || '';
        return location.pathname + ':' + COMPACT_PREFIX + JSON.stringify([kind, turnId, messageId, widgetId, index]);
    }

    function compactEnabled(kind) {
        return kind === 'writing' ? state.config.autoCompactWriting : state.config.autoCompactCode;
    }

    function automationEnabled() {
        return state.config.autoCollapseAnalysis || state.config.autoCompactWriting || state.config.autoCompactCode;
    }

    function getManagedDisclosures(wrapper) {
        return getAnalysisDisclosures(wrapper).concat(getCompactDisclosures(wrapper));
    }

    function getCompactDisclosures(wrapper) {
        const result = [];
        for (const surface of wrapper.querySelectorAll(COMPACT_SURFACE)) {
            if (surface.closest(USER_CONTEXT + ', ' + EXCLUDED_CONTEXT) ||
                !surface.closest(ASSISTANT_CONTEXT)) continue;
            const activity = surface.closest('[data-talvt-turn-state]');
            if (activity && activity.getAttribute('data-talvt-turn-state') !== 'complete') continue;
            const kind = surface.matches(WRITING_SURFACE) ? 'writing' : 'code';
            const candidates = Array.from(surface.querySelectorAll(COMPACT_TOGGLE))
                .filter((button) => validCompactToggle(surface, button, kind));
            // A missing or ambiguous control is not a license to synthesize a click.
            if (candidates.length !== 1) continue;
            const button = candidates[0];
            result.push({ button, surface, kind, open: button.getAttribute('aria-expanded') === 'true' });
        }
        return result;
    }

    function validCompactToggle(surface, button, kind) {
        if (!(button instanceof HTMLButtonElement) || button.disabled ||
            button.getAttribute('aria-disabled') === 'true' || button.hasAttribute('aria-haspopup') ||
            button.closest(COMPACT_SURFACE) !== surface ||
            button.closest(USER_CONTEXT + ', ' + EXCLUDED_CONTEXT)) return false;
        const expanded = button.getAttribute('aria-expanded');
        if (expanded !== 'true' && expanded !== 'false') return false;
        const id = button.getAttribute('aria-controls')?.trim();
        if (!id || /\s/.test(id)) return false;
        const target = document.getElementById(id);
        if (!(target instanceof HTMLElement) || target.closest(COMPACT_SURFACE) !== surface ||
            target.contains(button) || button.contains(target)) return false;
        if (kind === 'writing') {
            // The observed native Show more control is a sibling of the preview.
            return button.parentElement === target.parentElement &&
                Boolean(target.querySelector('[role="textbox"]'));
        }
        // Code is opt-in, and only a native toggle linked to the actual code body
        // qualifies. Copy, download, language menus, and arbitrary disclosures do not.
        return Boolean(button.closest('[data-code-block-controls="true"]')) &&
            (target.matches('pre') || Boolean(target.querySelector('pre')));
    }

    function compactBusy(disclosure) {
        const { surface, button } = disclosure;
        if (!surface) return false;
        if (surface.querySelector(EDITABLE)) return true;
        const active = document.activeElement;
        if (active && active !== button && surface.contains(active)) return true;
        const selection = window.getSelection();
        return Boolean(selection && !selection.isCollapsed &&
            ((selection.anchorNode && surface.contains(selection.anchorNode)) ||
             (selection.focusNode && surface.contains(selection.focusNode))));
    }

    function rememberReasoning(key, open) {
        if (!key || state.handledReasoning.get(key) === open) return false;
        state.handledReasoning.delete(key);
        state.handledReasoning.set(key, open);
        while (state.handledReasoning.size > MAX_REASONING_STATES) {
            state.handledReasoning.delete(state.handledReasoning.keys().next().value);
        }
        return true;
    }

    function nativeActivityBody(disclosure) {
        if (disclosure.kind || state.domMode !== DOM_MODE.native) return null;
        const header = disclosure.button.parentElement;
        if (!header?.matches(ACTIVITY_HEADER) ||
            !header.closest('[data-talvt-turn-state="complete"]') ||
            !header.closest(ACTIVITY_STACK)) return null;
        const nested = header.nextElementSibling;
        if (nested?.matches(NATIVE_BODY)) return nested;
        const row = header.parentElement;
        const body = row?.nextElementSibling;
        if (body?.matches('div') && body.querySelector(':scope > ' + ACTIVITY_STACK)) return body;
        return null;
    }

    function hasActivityGuardStyles() {
        try {
            const sheet = document.getElementById(APP + '-style')?.sheet;
            if (!sheet || !ACTIVITY_GUARD_SELECTORS.every(selector =>
                window.CSS?.supports('selector(' + selector + ')'))) return false;
            // CSSOM silently omits invalid rules. Do not activate the one-shot
            // guard or claim it is working unless both rules actually exist.
            const rules = Array.from(sheet.cssRules).filter(rule =>
                rule.selectorText?.includes('[' + LOCK_ATTR + '=') &&
                rule.style?.getPropertyValue('display') === 'none' &&
                rule.style?.getPropertyPriority('display') === 'important');
            return rules.length === ACTIVITY_GUARD_SELECTORS.length;
        } catch {
            return false;
        }
    }

    function syncNativeGuard() {
        if (!state.root?.isConnected) return;
        const enabled = state.domMode === DOM_MODE.native && state.config.autoCollapseAnalysis &&
            !state.paused && !state.safetyPaused && currentRouteKey() === state.routeKey &&
            hasActivityGuardStyles();
        if (enabled) {
            if (state.root.getAttribute(LOCK_ATTR) !== '1') state.root.setAttribute(LOCK_ATTR, '1');
        } else if (state.root.hasAttribute(LOCK_ATTR)) {
            clearNativeGuard();
        }
    }

    function clearNativeGuard() {
        state.manualOpenNodes = new WeakMap();
        state.root?.removeAttribute(LOCK_ATTR);
        state.root?.querySelectorAll('[' + OPEN_ATTR + ']').forEach(el => el.removeAttribute(OPEN_ATTR));
    }

    function guardedDisclosure(disclosure) {
        return state.root?.getAttribute(LOCK_ATTR) === '1' && nativeActivityBody(disclosure);
    }

    function visuallyOpen(disclosure) {
        return disclosure.open && !(guardedDisclosure(disclosure) &&
            !disclosure.button.parentElement.hasAttribute(OPEN_ATTR));
    }

    function clearReusedManualHeaders() {
        for (const header of state.root?.querySelectorAll('[' + OPEN_ATTR + ']') || []) {
            const button = header.querySelector(':scope > ' + MODERN_DISCLOSURE);
            const wrapper = button?.closest(SELECTORS.modernTurn);
            if (!wrapper || state.manualOpenNodes.get(button) !== getReasoningKey(wrapper, {button})) {
                header.removeAttribute(OPEN_ATTR);
            }
        }
    }

    function rememberClosedActivity(key) {
        state.closedActivityKeys.add(key);
        while (state.closedActivityKeys.size > MAX_REASONING_STATES) {
            state.closedActivityKeys.delete(state.closedActivityKeys.values().next().value);
        }
    }

    function handleManualReasoning(event) {
        if (state.destroyed || !event.isTrusted || !state.root?.isConnected ||
            currentRouteKey() !== state.routeKey) return;
        const button = event.target instanceof Element ? event.target.closest('button') : null;
        if (!button || !state.root.contains(button)) return;
        const wrapper = button.closest(state.domMode === DOM_MODE.native
            ? SELECTORS.modernTurn : SELECTORS.legacyWrapper);
        if (!wrapper) return;
        const disclosure = getManagedDisclosures(wrapper).find((item) => item.button === button);
        if (!disclosure || (disclosure.kind && !compactEnabled(disclosure.kind))) return;
        const key = getReasoningKey(wrapper, disclosure);
        if (!key) return;
        const body = guardedDisclosure(disclosure);
        const target = !visuallyOpen(disclosure);
        if (state.domMode === DOM_MODE.native) {
            if (target) state.manualOpenNodes.set(button, key);
            else state.manualOpenNodes.delete(button);
        }
        if (body) {
            const header = button.parentElement;
            if (target) header.setAttribute(OPEN_ATTR, '1');
            else header.removeAttribute(OPEN_ATTR);
            // React may already have remounted this disclosure as expanded.
            // Reveal the existing native body without toggling it closed again.
            // This is only a trusted user gesture on a verified activity header.
            if (target && disclosure.open) {
                event.preventDefault();
                event.stopImmediatePropagation();
            }
        }
        rememberReasoning(key, target);
        state.reasoningNodes.set(button, {
            key, target, attempts: 0, manualUntil: Date.now() + MANUAL_SETTLE_MS, verifyAt: 0,
        });
        saveHandledReasoning();
        scheduleReasoning(REASONING_VERIFY_MS);
    }

    function scheduleReasoning(delay = 120) {
        if (state.destroyed || state.paused || state.reasoningTimer ||
            !automationEnabled()) return;
        state.reasoningTimer = window.setTimeout(() => {
            state.reasoningTimer = 0;
            if (currentRouteKey() !== state.routeKey || !runDomSelfCheck(false)) return;
            collapseOpenAnalyses(true);
            updatePanel();
        }, delay);
    }

    function resetReasoningHistory() {
        const count = state.handledReasoning.size;
        state.handledReasoning.clear();
        state.reasoningNodes = new WeakMap();
        state.manualOpenNodes = new WeakMap();
        state.closedActivityKeys.clear();
        state.root?.querySelectorAll('[' + OPEN_ATTR + ']').forEach(el => el.removeAttribute(OPEN_ATTR));
        state.reversibleCompact.clear();

        try {
            sessionStorage.removeItem(HANDLED_REASONING_KEY);
        } catch {
        }

        scheduleReasoning();
        updatePanel();
        showFeedback(t.feedbackReset(count));
        return count;
    }

    function handleKeyboardShortcut(event) {
        if (
            state.destroyed ||
            !state.config.keyboardShortcut ||
            event.repeat ||
            event.code !== 'KeyO' ||
            !event.altKey ||
            !event.shiftKey ||
            event.ctrlKey ||
            event.metaKey
        ) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();
        runFullOptimize();
    }

    function isChatGPTStreaming() {
        return Boolean(document.querySelector(SELECTORS.streaming));
    }

    function clampInt(value, min, max, fallback) {
        const n = Number.parseInt(value, 10);
        return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
    }

    function currentRouteKey() {
        return `${location.pathname}${location.search}`;
    }

    function runDomSelfCheck(force = false) {
        if (state.destroyed) return false;

        if (!state.root?.isConnected) {
            if (force) showFeedback(t.noConversation);
            return false;
        }

        let contractOk = false;

        if (state.domMode === DOM_MODE.native) {
            const conversation = document.querySelector(SELECTORS.modernConversation);
            const wrappers = getWrappers();

            contractOk = Boolean(
                conversation &&
                conversation === state.root &&
                wrappers.every((el) =>
                    el instanceof HTMLElement &&
                    el.matches(SELECTORS.modernTurn) &&
                    Boolean(el.getAttribute('data-turn-key'))
                )
            );
        } else if (state.domMode === DOM_MODE.legacy) {
            const thread = document.querySelector(SELECTORS.legacyThread);

            if (thread) {
                const discoveredWrappers = Array.from(
                    thread.querySelectorAll(SELECTORS.legacyWrapper)
                ).filter((el) =>
                    el instanceof HTMLElement &&
                    el.dataset.turnIdContainer !== 'client-created-root'
                );

                const directWrappers = getWrappers();
                contractOk =
                    thread.contains(state.root) &&
                    (discoveredWrappers.length === 0 || directWrappers.length > 0);
            }
        }

        if (contractOk) {
            state.domMismatchCount = 0;

            if (state.safetyPaused) {
                state.safetyPaused = false;
                state.safetyIssue = '';
                setStatus(t.safetyRestored);
                showFeedback(t.safetyRestored);
                updatePanel();
            }

            return true;
        }

        clearOurMarks();
        clearNativeGuard();
        state.domMismatchCount += 1;

        if (force || state.domMismatchCount >= 3) {
            const firstPause = !state.safetyPaused;
            state.safetyPaused = true;
            state.safetyIssue = 'conversation-root';
            setStatus(t.safetyPaused);

            if (firstPause || force) {
                showFeedback(t.safetyPaused);
            }

            updatePanel();
        }

        return false;
    }

    function injectDocumentStyles() {
        const mount = document.head || document.documentElement;
        const existing = document.getElementById(`${APP}-style`);
        if (existing) {
            if (existing.parentNode !== mount) mount.appendChild(existing);
            return;
        }

        const style = document.createElement('style');
        style.id = `${APP}-style`;
        // Separate rules so one invalid selector cannot discard the other.
        style.textContent = `
            ${ACTIVITY_GUARD_SELECTORS.map(selector => selector + ' { display: none !important; }').join('\n')}
            [${HIDDEN_ATTR}="1"] { display: none !important; }
            ${SELECTORS.legacyThread}[${CV_ATTR}="1"] ${SELECTORS.legacyTurn} {
                content-visibility: auto !important;
                contain-intrinsic-size: auto 240px !important;
            }
        `;
        mount.appendChild(style);
    }

    function scheduleInit(delay = 100) {
        window.clearTimeout(state.initTimer);
        state.initTimer = window.setTimeout(init, delay);
    }

    function init() {
        if (state.destroyed) return;
        injectDocumentStyles();
        createPanel();

        const discovered = discoverConversationRoot();
        if (!discovered) {
            setStatus(t.waitingDom);
            updatePanel();
            scheduleInit(700);
            return;
        }

        if (state.root !== discovered.root || state.domMode !== discovered.mode) {
            clearOurMarks();
            resetObserver();
            state.root = discovered.root;
            state.thread = discovered.thread;
            state.domMode = discovered.mode;
            state.scroller = discoverScroller(state.root);
            observeRoot(state.root);
        }

        if (!runDomSelfCheck(false)) return;
        syncNativeGuard();
        applyContentVisibilityFlag();
        state.lastStreaming = isChatGPTStreaming();
        scheduleReasoning();
        updatePanel();

        if (state.config.autoOptimize && !state.paused) {
            scheduleApply(250);
        } else {
            setStatus(state.paused ? t.paused : t.autoOff);
        }
    }

    function discoverConversationRoot() {
        const modernConversation = document.querySelector(SELECTORS.modernConversation);
        if (modernConversation) {
            // An empty virtual window during navigation is not a legacy conversation.
            return { thread: modernConversation, root: modernConversation, mode: DOM_MODE.native };
        }

        const thread = document.querySelector(SELECTORS.legacyThread);
        if (!thread) return null;

        const candidates = Array.from(
            thread.querySelectorAll(SELECTORS.legacyWrapper)
        );
        if (!candidates.length) return null;

        const parentCounts = new Map();
        for (const wrapper of candidates) {
            const parent = wrapper.parentElement;
            if (!parent) continue;
            parentCounts.set(parent, (parentCounts.get(parent) || 0) + 1);
        }

        let root = null;
        let bestCount = 0;
        for (const [parent, count] of parentCounts) {
            if (count > bestCount) {
                root = parent;
                bestCount = count;
            }
        }

        return root ? { thread, root, mode: DOM_MODE.legacy } : null;
    }

    function getWrappers() {
        if (!state.root?.isConnected) return [];

        if (state.domMode === DOM_MODE.native) {
            return Array.from(
                state.root.querySelectorAll(SELECTORS.modernTurn)
            ).filter((el) =>
                el instanceof HTMLElement &&
                Boolean(el.getAttribute('data-turn-key'))
            );
        }

        return Array.from(state.root.children).filter((el) =>
            el instanceof HTMLElement &&
            el.matches(SELECTORS.legacyWrapper) &&
            el.dataset.turnIdContainer !== 'client-created-root'
        );
    }

    function discoverScroller(start) {
        const modernScroller = start?.closest?.(SELECTORS.modernScroller);
        if (modernScroller instanceof HTMLElement) return modernScroller;

        for (let el = start; el && el !== document.body; el = el.parentElement) {
            const overflowY = getComputedStyle(el).overflowY;
            const canScroll = overflowY === 'auto' || overflowY === 'scroll';
            if (canScroll && el.scrollHeight > el.clientHeight + 2) return el;
        }

        return document.scrollingElement || document.documentElement;
    }

    function observeRoot(root) {
        const relevant = [SELECTORS.modernTurn, SELECTORS.legacyWrapper, MODERN_DISCLOSURE, COMPACT_TOGGLE, COMPACT_SURFACE,
            '[data-talvt-turn-state]', ACTIVITY_STACK, ACTIVITY_HEADER,
            '[data-chatgpt-agent-turn-start]', 'span.block'].join(', ');
        state.observer = new MutationObserver((records) => {
            if (state.destroyed || state.paused || currentRouteKey() !== state.routeKey) return;
            if (state.domMode === DOM_MODE.legacy &&
                records.some((record) => record.type === 'childList' && record.target === root)) {
                scheduleApply(300);
            }
            if (records.some((record) => record.type === 'attributes' ||
                Array.from(record.addedNodes).concat(Array.from(record.removedNodes)).some((node) =>
                    node instanceof Element && (node.matches(relevant) || node.querySelector(relevant))))) {
                clearReusedManualHeaders();
                scheduleReasoning();
            }
        });
        state.observer.observe(root, {
            childList: true, subtree: true, attributes: true,
            attributeFilter: ['aria-expanded', 'aria-busy', 'aria-labelledby', 'aria-controls',
                'aria-hidden', 'hidden', 'data-talvt-turn-state', 'data-turn-key',
                'data-content-search-turn-key', 'data-spacing'],
        });
    }

    function resetObserver() {
        clearNativeGuard();
        state.observer?.disconnect();
        window.clearTimeout(state.applyTimer);
        window.clearTimeout(state.reasoningTimer);
        state.reasoningTimer = 0;
        state.observer = null;
        state.root = null;
        state.thread = null;
        state.domMode = null;
        state.scroller = null;
    }

    function scheduleApply(delay = 250) {
        window.clearTimeout(state.applyTimer);
        state.applyTimer = window.setTimeout(() => {
            if (!state.destroyed) applyOptimization(false);
        }, delay);
    }

    function runFullOptimize() {
        state.paused = false;
        state.revealedExtra = 0;

        if (!state.root?.isConnected) {
            scheduleInit(0);
            showFeedback(t.noConversation);
            return;
        }

        if (!runDomSelfCheck(true)) return;
        syncNativeGuard();

        const collapsed = collapseOpenAnalyses(true, true);
        optimizeNow(true);

        window.setTimeout(() => {
            const stats = collectStats();
            showFeedback(
                stats.nativeVirtualization
                    ? t.feedbackOptimizeNative(collapsed)
                    : t.feedbackOptimize(stats.hiddenWrappers, collapsed)
            );
        }, 180);
    }

    function runDomOnlyOptimize() {
        state.paused = false;
        state.revealedExtra = 0;

        if (!state.root?.isConnected) {
            scheduleInit(0);
            showFeedback(t.noConversation);
            return;
        }

        if (!runDomSelfCheck(true)) return;

        optimizeNow(true);

        window.setTimeout(() => {
            const stats = collectStats();
            showFeedback(
                stats.nativeVirtualization
                    ? t.feedbackNative
                    : t.feedbackDomOnly(stats.hiddenWrappers)
            );
        }, 180);
    }

    function optimizeNow(scrollToBottomIfNeeded = false) {
        state.paused = false;
        state.revealedExtra = 0;

        if (!state.root?.isConnected) {
            scheduleInit(0);
            return;
        }

        if (state.domMode === DOM_MODE.native) {
            syncNativeGuard();
            applyOptimization(true);
            return;
        }

        const scroller = state.scroller || discoverScroller(state.root);

        if (scrollToBottomIfNeeded && scroller && !isNearBottom(scroller, 1000)) {
            scroller.scrollTop = scroller.scrollHeight;
            requestAnimationFrame(() =>
                requestAnimationFrame(() => applyOptimization(true))
            );
            return;
        }

        applyOptimization(true);
    }

    function applyOptimization(force = false) {
        if (
            state.destroyed ||
            state.paused ||
            state.safetyPaused ||
            currentRouteKey() !== state.routeKey ||
            !state.root?.isConnected || !runDomSelfCheck(false)
        ) return;

        const wrappers = getWrappers();
        if (!wrappers.length) {
            updatePanel();
            return;
        }

        if (state.domMode === DOM_MODE.native) {
            clearOurMarks();
            state.revealedExtra = 0;
            applyContentVisibilityFlag();
            setStatus(t.nativeActive);
            updatePanel();
            return;
        }

        const thresholdReached = wrappers.length >= state.config.autoThreshold;

        if (!force && (!state.config.autoOptimize || !thresholdReached)) {
            restoreAll(false);
            setStatus(
                thresholdReached
                    ? t.autoOff
                    : t.waitingThreshold(wrappers.length, state.config.autoThreshold)
            );
            updatePanel();
            return;
        }

        state.scroller = state.scroller?.isConnected
            ? state.scroller
            : discoverScroller(state.root);

        const scroller = state.scroller;
        if (!force && scroller && !isNearBottom(scroller, 900)) {
            setStatus(t.scrollDown);
            updatePanel();
            return;
        }

        const keep = Math.min(
            wrappers.length,
            state.config.keepRecent + state.revealedExtra
        );
        const hideCount = Math.max(0, wrappers.length - keep);
        const wasNearBottom = scroller ? isNearBottom(scroller, 900) : false;
        const distanceFromBottom = scroller ? getDistanceFromBottom(scroller) : 0;
        const active = document.activeElement;
        let hidden = 0;

        for (let i = 0; i < wrappers.length; i += 1) {
            const wrapper = wrappers[i];
            let shouldHide = i < hideCount;

            if (shouldHide && active && wrapper.contains(active)) {
                shouldHide = false;
            }

            if (shouldHide) {
                wrapper.setAttribute(HIDDEN_ATTR, '1');
                hidden += 1;
            } else {
                wrapper.removeAttribute(HIDDEN_ATTR);
            }
        }

        if (wasNearBottom && scroller) {
            preserveBottomDistance(scroller, distanceFromBottom);
        }

        applyContentVisibilityFlag();
        setStatus(hidden ? t.hidden(hidden) : t.nothingToHide);
        updatePanel();
    }

    function revealOlder(count) {
        if (!state.root?.isConnected) return;

        if (state.domMode === DOM_MODE.native) {
            setStatus(t.nativeActive);
            updatePanel();
            return;
        }

        const wrappers = getWrappers();
        const hidden = wrappers.filter(
            (wrapper) => wrapper.getAttribute(HIDDEN_ATTR) === '1'
        );

        if (!hidden.length) {
            setStatus(t.allVisible);
            updatePanel();
            return;
        }

        const amount = Math.min(
            hidden.length,
            clampInt(count, 1, 500, state.config.revealStep)
        );
        const anchor = wrappers.find(
            (wrapper) => wrapper.getAttribute(HIDDEN_ATTR) !== '1' && wrapper.isConnected
        );
        const beforeTop = anchor?.getBoundingClientRect().top ?? null;
        const scroller = state.scroller || discoverScroller(state.root);

        state.revealedExtra += amount;
        for (const wrapper of hidden.slice(-amount)) {
            wrapper.removeAttribute(HIDDEN_ATTR);
        }

        if (anchor && beforeTop !== null && scroller) {
            const route = state.routeKey;
            requestAnimationFrame(() => {
                if (state.destroyed || currentRouteKey() !== route || !anchor.isConnected || !scroller.isConnected) return;
                const delta = anchor.getBoundingClientRect().top - beforeTop;
                if (Number.isFinite(delta) && Math.abs(delta) > 0.5) {
                    scroller.scrollTop += delta;
                }
                updatePanel();
            });
        } else {
            updatePanel();
        }

        setStatus(t.revealed(amount));
    }

    function restoreAll(pauseAfterRestore = false) {
        for (const wrapper of document.querySelectorAll(`[${HIDDEN_ATTR}="1"]`)) {
            wrapper.removeAttribute(HIDDEN_ATTR);
        }

        state.revealedExtra = 0;

        if (pauseAfterRestore) {
            state.paused = true;
            setStatus(t.restoredPaused);
        }
        if (state.paused) {
            clearOurMarks();
            clearNativeGuard();
            window.clearTimeout(state.reasoningTimer);
            state.reasoningTimer = 0;
        }

        updatePanel();
    }

    function clearOurMarks() {
        for (const el of document.querySelectorAll(`[${HIDDEN_ATTR}], [${CV_ATTR}]`)) {
            el.removeAttribute(HIDDEN_ATTR);
            el.removeAttribute(CV_ATTR);
        }
    }

    function applyContentVisibilityFlag() {
        if (state.domMode !== DOM_MODE.legacy || state.paused || state.safetyPaused) {
            document.querySelectorAll('[' + CV_ATTR + ']').forEach((el) => el.removeAttribute(CV_ATTR));
            return;
        }

        const thread =
            state.thread?.isConnected
                ? state.thread
                : document.querySelector(SELECTORS.legacyThread);

        if (!thread) return;

        if (state.config.contentVisibility) {
            thread.setAttribute(CV_ATTR, '1');
        } else {
            thread.removeAttribute(CV_ATTR);
        }
    }

    function collapseOpenAnalyses(scanAll = false, force = false, reasoningOnly = false) {
        if (state.destroyed || state.safetyPaused || (!force && state.paused) ||
            (!force && !automationEnabled()) ||
            currentRouteKey() !== state.routeKey || isChatGPTStreaming() ||
            !state.root?.isConnected || !runDomSelfCheck(false)) return 0;

        state.lastReasoningScan = Date.now();
        const wrappers = getWrappers();
        const targets = scanAll || state.domMode === DOM_MODE.native ? wrappers : wrappers.slice(-12);
        const disclosures = targets.flatMap((wrapper) =>
            (reasoningOnly ? getAnalysisDisclosures(wrapper) : getManagedDisclosures(wrapper))
                .filter((disclosure) => disclosure.kind
                    ? compactEnabled(disclosure.kind)
                    : force || state.config.autoCollapseAnalysis)
                .map((disclosure) => ({ ...disclosure, key: getReasoningKey(wrapper, disclosure) })));
        // Nested analysis sections are later in document order than their outer
        // activity header. Close the inner controls before the outer header can
        // hide/unmount them. A later reconciliation can restore manual choices.
        disclosures.reverse();
        let requested = 0;
        let changed = false;
        let verify = false;
        const now = Date.now();

        if (force) {
            state.manualOpenNodes = new WeakMap();
            state.root.querySelectorAll('[' + OPEN_ATTR + ']').forEach(el => el.removeAttribute(OPEN_ATTR));
            const prefix = location.pathname + ':';
            // Optimize applies to remembered reasoning in the whole conversation,
            // not only to the current native virtual window.
            for (const [key, open] of Array.from(state.handledReasoning.entries())) {
                if (open && key.startsWith(prefix) && !key.startsWith(prefix + COMPACT_PREFIX)) {
                    changed = rememberReasoning(key, false) || changed;
                }
            }
        }

        for (const disclosure of disclosures) {
            const { button, key } = disclosure;
            if (!key) continue;
            if (disclosure.kind && compactBusy(disclosure)) continue;
            // Explicit Optimize clears manual overrides for all recognized blocks,
            // including ones detached by a preceding parent collapse.
            if (force) {
                changed = rememberReasoning(key, false) || changed;
                state.reasoningNodes.delete(button);
            }
            if (!button.isConnected || !state.root.contains(button) ||
                button.closest('[hidden], [aria-hidden="true"], [data-cgpt-lco-hidden="1"], ' + USER_CONTEXT)) continue;
            const open = disclosure.kind || state.domMode === DOM_MODE.native
                ? button.getAttribute('aria-expanded') === 'true' : disclosure.open;
            if (disclosure.kind && open) {
                state.reversibleCompact.add(key);
                while (state.reversibleCompact.size > MAX_REASONING_STATES) {
                    state.reversibleCompact.delete(state.reversibleCompact.values().next().value);
                }
            }
            if (!state.handledReasoning.has(key)) changed = rememberReasoning(key, false) || changed;
            let target = state.handledReasoning.get(key);
            let record = state.reasoningNodes.get(button);
            // Manual opens belong to the mounted control only. Never replay an
            // opening click when a virtualized turn comes back into view.
            if (state.domMode === DOM_MODE.native && target &&
                state.manualOpenNodes.get(button) !== key) {
                changed = rememberReasoning(key, false) || changed;
                target = false;
            }
            const body = guardedDisclosure(disclosure);
            if (body && !target) {
                button.parentElement.removeAttribute(OPEN_ATTR);
                // The stylesheet keeps this exact body visually closed from
                // its first layout. Request a native close once per stable key,
                // not once per React mount, even if the native state resets.
                if (!open) {
                    rememberClosedActivity(key);
                    continue;
                }
                if (state.closedActivityKeys.has(key)) continue;
                rememberClosedActivity(key);
                if (!button.disabled && button.isConnected) {
                    button.click();
                    requested += 1;
                }
                continue;
            }
            if (!record || record.key !== key || record.target !== target) {
                record = { key, target, attempts: 0, manualUntil: 0, verifyAt: 0 };
                state.reasoningNodes.set(button, record);
            }
            if (record.manualUntil) {
                if (open === target) {
                    record.manualUntil = 0;
                } else if (now < record.manualUntil) {
                    verify = true;
                    continue;
                } else {
                    // Native handler did not accept the interaction. Do not fight it.
                    changed = rememberReasoning(key, open) || changed;
                    record.target = open;
                    record.manualUntil = 0;
                    target = open;
                }
            }
            if (open === target) {
                record.verifyAt = 0;
                continue;
            }
            // Some Writing Blocks replace their Show more button with an editable
            // surface. Never auto-open such a one-way control on scroll/remount.
            // Restore a manual open only after seeing a reversible native toggle
            // for this exact stable block during this page lifetime.
            if (target && state.domMode === DOM_MODE.native) continue;
            if (disclosure.kind && target && !state.reversibleCompact.has(key)) continue;
            if (record.verifyAt > now) {
                verify = true;
                continue;
            }
            if (record.attempts >= MAX_TOGGLE_ATTEMPTS) continue;
            if (button.disabled || !button.isConnected) continue;
            record.attempts += 1;
            record.verifyAt = now + REASONING_VERIFY_MS;
            button.click();
            requested += open && !target ? 1 : 0;
            verify = true;
        }
        if (changed) saveHandledReasoning();
        if (verify) scheduleReasoning(REASONING_VERIFY_MS);
        return requested;
    }

    function getAnalysisDisclosures(wrapper) {
        if (wrapper.matches(SELECTORS.modernTurn)) {
            return Array.from(
                wrapper.querySelectorAll(MODERN_DISCLOSURE)
            )
                .map((button) => getModernAnalysisDisclosure(button))
                .filter(Boolean);
        }

        const disclosures = [];

        for (const summary of wrapper.querySelectorAll('span.block')) {
            if (!(summary instanceof HTMLElement) || summary.closest(USER_CONTEXT + ', ' + EXCLUDED_CONTEXT)) continue;
            if (summary.closest('[class*="group/tool-message"]')) continue;

            const disclosure = getLegacyAnalysisDisclosure(summary);
            if (disclosure) disclosures.push(disclosure);
        }

        return disclosures;
    }

    function getModernAnalysisDisclosure(button) {
        if (!(button instanceof HTMLButtonElement) || button.disabled) return null;

        const expanded = button.getAttribute('aria-expanded');
        if (expanded !== 'true' && expanded !== 'false') return null;

        const header = button.parentElement;
        const container = header?.parentElement;
        if (!(header instanceof HTMLElement) || !(container instanceof HTMLElement)) {
            return null;
        }

        if (!header.matches(ACTIVITY_HEADER) ||
            Array.from(header.children).filter((el) => el.matches(MODERN_DISCLOSURE)).length !== 1) return null;
        if (button.closest(USER_CONTEXT + ', ' + EXCLUDED_CONTEXT + ', ' + COMPACT_SURFACE) ||
            button.hasAttribute('aria-haspopup') || button.getAttribute('aria-disabled') === 'true') return null;

        const activityTurn = button.closest('[data-talvt-turn-state]');
        if (activityTurn && activityTurn.getAttribute('data-talvt-turn-state') !== 'complete') return null;
        const activityStack = button.closest(ACTIVITY_STACK);
        // The real outer thinking header is inside a separate flex row.
        // Its body is a sibling of that row, not a sibling of the header.
        // Accept the known row/stack contract without relying on open-state
        // siblings, since ChatGPT can keep or detach the body on collapse.
        const rowBody = container.nextElementSibling;
        const rowHasActivity = Boolean(rowBody &&
            (rowBody.matches(ACTIVITY_STACK) || rowBody.querySelector(ACTIVITY_STACK)));
        if (!activityStack && !(activityTurn && rowHasActivity &&
            activityTurn.querySelector('[data-chatgpt-agent-turn-start]'))) return null;

        const labelId = button.getAttribute('aria-labelledby');
        const label = labelId ? document.getElementById(labelId) : null;
        if (!(label instanceof HTMLElement) || !header.contains(label) || button.contains(label)) {
            return null;
        }

        return { button, open: expanded === 'true' };
    }

    function getLegacyAnalysisDisclosure(summary) {
        const button = summary.querySelector('button');
        if (!(button instanceof HTMLButtonElement) || button.disabled) return null;

        const content = summary.nextElementSibling;
        if (!(content instanceof HTMLElement)) return null;

        if (isOpenLegacyAnalysisContent(content)) {
            return { button, open: true };
        }

        if (content.getAttribute('data-message-author-role') === 'assistant') {
            return { button, open: false };
        }

        return null;
    }

    function countOpenAnalyses() {
        if (!state.root?.isConnected) return 0;

        let open = 0;

        for (const wrapper of getWrappers()) {
            for (const disclosure of getAnalysisDisclosures(wrapper)) {
                if (visuallyOpen(disclosure)) open += 1;
            }
        }

        return open;
    }

    function handledReasoningForCurrentRoute() {
        const prefix = `${location.pathname}:`;
        let count = 0;

        for (const key of state.handledReasoning.keys()) {
            if (key.startsWith(prefix) && !key.startsWith(prefix + COMPACT_PREFIX)) count += 1;
        }

        return count;
    }

    function collectCompactStats() {
        const result = { writing: 0, code: 0, open: 0, remembered: 0 };
        for (const wrapper of getWrappers()) {
            for (const disclosure of getCompactDisclosures(wrapper)) {
                result[disclosure.kind] += 1;
                if (disclosure.open) result.open += 1;
            }
        }
        const prefix = location.pathname + ':' + COMPACT_PREFIX;
        for (const key of state.handledReasoning.keys()) {
            if (key.startsWith(prefix)) result.remembered += 1;
        }
        return Object.freeze(result);
    }

    function isOpenLegacyAnalysisContent(element) {
        if (
            element.tagName !== 'DIV' ||
            element.hasAttribute('data-message-author-role')
        ) {
            return false;
        }

        const inlineHeight = element.style.height?.trim().toLowerCase() || '';
        if (inlineHeight !== 'auto') return false;
        if (element.querySelector('[data-message-author-role]')) return false;

        return Boolean(element.querySelector('.markdown, pre, [data-start]'));
    }

    function isNearBottom(scroller, tolerance = 700) {
        return getDistanceFromBottom(scroller) <= tolerance;
    }

    function getDistanceFromBottom(scroller) {
        return Math.max(
            0,
            scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop
        );
    }

    function preserveBottomDistance(scroller, distance) {
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                const target =
                    scroller.scrollHeight -
                    scroller.clientHeight -
                    Math.max(0, distance);
                scroller.scrollTop = Math.max(0, target);
            });
        });
    }

    function collectDisclosureDiagnostics() {
        const result = {
            version: '0.8.4',
            mode: state.domMode,
            activityGuardStylesReady: hasActivityGuardStyles(),
            activityGuardActive: state.root?.getAttribute(LOCK_ATTR) === '1',
            streaming: isChatGPTStreaming(),
            paused: state.paused,
            safetyPaused: state.safetyPaused,
            autoCollapseAnalysis: state.config.autoCollapseAnalysis,
            candidates: 0,
            recognized: 0,
            open: 0,
            hidden: 0,
            manualOpen: 0,
            pendingClose: 0,
            retryExhausted: 0,
            missingKey: 0,
            visuallyLocked: 0,
            nativeOpenButLocked: 0,
            onceClosedKeys: state.closedActivityKeys.size,
        };
        for (const wrapper of getWrappers()) {
            if (state.domMode === DOM_MODE.native) {
                result.candidates += wrapper.querySelectorAll(ACTIVITY_HEADER + ' > ' + MODERN_DISCLOSURE).length;
            }
            for (const disclosure of getAnalysisDisclosures(wrapper)) {
                result.recognized += 1;
                const guardedBody = guardedDisclosure(disclosure);
                if (guardedBody && !disclosure.button.parentElement.hasAttribute(OPEN_ATTR) &&
                    getComputedStyle(guardedBody).display === 'none') {
                    result.visuallyLocked += 1;
                    if (disclosure.open) result.nativeOpenButLocked += 1;
                }
                if (!visuallyOpen(disclosure)) continue;
                result.open += 1;
                const key = getReasoningKey(wrapper, disclosure);
                if (!key) {
                    result.missingKey += 1;
                    continue;
                }
                if (disclosure.button.closest('[hidden], [aria-hidden="true"], [data-cgpt-lco-hidden="1"]')) {
                    result.hidden += 1;
                    continue;
                }
                if (state.handledReasoning.get(key) === true) {
                    result.manualOpen += 1;
                    continue;
                }
                const record = state.reasoningNodes.get(disclosure.button);
                if (record?.key === key && record.attempts >= MAX_TOGGLE_ATTEMPTS) {
                    result.retryExhausted += 1;
                    continue;
                }
                result.pendingClose += 1;
            }
        }
        return Object.freeze(result);
    }

    function collectStats() {
        const wrappers = getWrappers();
        const hidden = wrappers.filter(
            (wrapper) => wrapper.getAttribute(HIDDEN_ATTR) === '1'
        ).length;
        const nativeVirtualization = state.domMode === DOM_MODE.native;
        const rendered = nativeVirtualization
            ? wrappers.length
            : wrappers.filter(
                (wrapper) => wrapper.querySelector(SELECTORS.legacyTurn)
            ).length;

        return Object.freeze({
            route: state.routeKey,
            domMode: state.domMode,
            nativeVirtualization,
            wrappers: wrappers.length,
            visibleWrappers: wrappers.length - hidden,
            hiddenWrappers: hidden,
            renderedTurns: rendered,
            nativeVirtualizedPlaceholders: nativeVirtualization
                ? null
                : wrappers.length - rendered,
            keepRecent: state.config.keepRecent,
            revealedExtra: state.revealedExtra,
            autoThreshold: state.config.autoThreshold,
            autoOptimize: state.config.autoOptimize,
            contentVisibility: state.config.contentVisibility,
            autoCollapseAnalysis: state.config.autoCollapseAnalysis,
            keyboardShortcut: state.config.keyboardShortcut,
            handledReasoning: handledReasoningForCurrentRoute(),
            handledReasoningTotal: state.handledReasoning.size,
            openPreferences: Array.from(state.handledReasoning.values()).filter(Boolean).length,
            version: '0.8.4',
            autoCompactWriting: state.config.autoCompactWriting,
            autoCompactCode: state.config.autoCompactCode,
            compact: collectCompactStats(),
            openReasoning: countOpenAnalyses(),
            streaming: isChatGPTStreaming(),
            safetyPaused: state.safetyPaused,
            safetyIssue: state.safetyIssue,
            paused: state.paused,
            status: state.lastStatus,
        });
    }

    function setStatus(text) {
        state.lastStatus = text;
    }

    function showFeedback(text, duration = FEEDBACK_MS) {
        if (!state.panel?.feedback) return;

        window.clearTimeout(state.feedbackTimer);

        const feedback = state.panel.feedback;
        feedback.textContent = text;
        feedback.classList.remove('show');
        void feedback.offsetWidth;
        feedback.classList.add('show');

        state.feedbackTimer = window.setTimeout(() => {
            feedback.classList.remove('show');
        }, duration);
    }

