              try {
                toElement.appendChild(newScript)
              } catch (e) {
              }
            })
          } // 执行完脚本后，执行这个函数
        }
      }
    }

    _s_haosou() {
      if (this.useItem.SiteTypeID === 3) {
      }
      return {
        SiteTypeID: 3,
