        Stype_Normal: "h3>a",
        FaviconType: "cite",
        FaviconAddTo: "h3",
        CounterType: ".results>div",
        BlockType: "h3 a",
        // TODO 增加这个
        MultiPageType: ".result li", // 多列模式下，待选择的元素，未来再说
        pager: {
          nextLink: "//div[@id='page']//a[text()='下一页>'] | id('snext')",
