              if (navigator.userAgent.toLowerCase().includes('macintosh')) {
                // MARK 为了兼容百度在safari下的
                url = url.replace('https://', 'http://');
              }
            }
            if (url === '') return;
            if (CONST.options.useItem.pageUrl === url) {
              console.error("[AC-Script]", "翻页到达底部了 - 或者异常 - 出现异常请直接反馈作者修改");
              return;
            }// 不会重复加载相同的页面
