            if (!curItem.hasAttribute('two-checked') || +attrV < 8) {
              const node = getTrueFatherChild(preNode, curItem, fatherNode)
              if (node) {
                return node
              }
            }
            curItem.setAttribute('two-checked', +attrV + 1)
            preNode = curItem
            curItem = fatherNode
            curHeight++
