			.replace(/第\s*\d+\s*[集话期章回]/g, '')
			.replace(/EP?\s*\d+/gi, '')
			.replace(/S\d+E\d+/gi, '')
			.replace(/\d+\s*[集话期]/g, '')
			.replace(/[\[\(（].*?[\]\)）]/g, '')
			.replace(/\s+/g, ' ')
			.trim();
