			if (cfg.isLive) for(const k of [37,1061,39,1063,67,77,78,88,90]) actList.delete(k);
			else {
				if (bRate) v.playbackRate = +localStorage.mvPlayRate || 1;
				v.addEventListener('ratechange', ev => {
